import React, { useState, useEffect } from "react";
import "bootstrap/dist/css/bootstrap.min.css";
import axios from "axios";
import live from "../../img/aulas-ao-vivo-coursifyme.jpg"; // Ajuste o caminho
import Aula from "../../../../educaweb-backend/models/Aula";

const AulaAluno = () => {
  const [aulas, setAulas] = useState([]);
  const [materiais, setMateriais] = useState([]);
  const [curso, setCurso] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const carregarDados = async () => {
      try {
        // 1. Obter dados do aluno (simplificado - em produção use autenticação)
        const alunoResponse = await axios.get("/api/alunos/me");
        const cursoId = alunoResponse.data.cursoId;

        if (cursoId) {
          // 2. Carregar dados em paralelo
          const [cursoResponse, aulasResponse, materiaisResponse] =
            await Promise.all([
              axios.get(`/api/cursos/${cursoId}`),
              axios.get(`/api/aulas/curso/${cursoId}`),
              axios.get(`/api/materiais/curso/${cursoId}`),
            ]);

          setCurso(cursoResponse.data);
          setAulas(aulasResponse.data);
          setMateriais(materiaisResponse.data);
        }
      } catch (error) {
        console.error("Erro ao carregar dados:", error);
      } finally {
        setLoading(false);
      }
    };

    carregarDados();
  }, []);

  if (loading) {
    return <div className="text-center mt-5">Carregando...</div>;
  }

  return (
    <div
      className="container-fluid d-flex flex-column align-items-center"
      style={{
        backgroundColor: "#E7EFF4",
        minHeight: "100vh",
        padding: "20px",
      }}
    >
      <nav className="nav nav-tabs mb-3 bg-white p-2 w-75 d-flex justify-content-center">
        <a className="nav-link" href="#">
          Cursos
        </a>
        <a className="nav-link active" href="#">
          Aulas
        </a>
        <a className="nav-link" href="#">
          Avaliações
        </a>
      </nav>

      <h2 className="mb-3 text-center">
        {curso ? `Aulas - ${curso.nome}` : "Aulas"}
      </h2>

      <div className="row w-75">
        {/* Aulas Ao Vivo */}
        <div className="col-md-6 text-center mb-4">
          <h4>Aulas Ao Vivo</h4>
          <div className="card p-3">
            <img src={live} alt="Aula ao vivo" className="img-fluid rounded" />
            <div className="d-flex justify-content-center mt-3">
              <button className="btn btn-primary me-2">Entrar na Aula</button>
              <button className="btn btn-outline-secondary">Agenda</button>
            </div>
          </div>
        </div>

        {/* Aulas Gravadas */}
        <div className="col-md-6">
          <h4>Aulas Gravadas</h4>
          <div className="list-group">
            {aulas.length > 0 ? (
              aulas.map((aula) => (
                <div
                  key={aula.id}
                  className="list-group-item d-flex justify-content-between align-items-center"
                >
                  <a
                    href={aula.videoUrl}
                    target="_blank"
                    rel="noopener noreferrer"
                  >
                    {aula.titulo}
                  </a>
                  <span className="badge bg-primary rounded-pill">Novo</span>
                </div>
              ))
            ) : (
              <div className="alert alert-info">Nenhuma aula disponível</div>
            )}
          </div>
        </div>
      </div>

      {/* Materiais de Apoio */}
      <div className="w-75 mt-4">
        <h4>Material de Apoio</h4>
        <div className="card p-3">
          {materiais.length > 0 ? (
            <div className="list-group">
              {materiais.map((material) => (
                <a
                  key={material.id}
                  href={material.arquivoUrl}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="list-group-item list-group-item-action d-flex justify-content-between"
                >
                  {material.nome}
                  <i className="bi bi-download"></i>
                </a>
              ))}
            </div>
          ) : (
            <div className="alert alert-info">Nenhum material disponível</div>
          )}
        </div>
      </div>
    </div>
  );
};

export default Aula;
